'use strict';
const {chromium}=require('playwright');
const BASE=process.env.MSOS4_TEST_URL||'http://127.0.0.1:8765/';
const NORTH=`North Canterbury Swimming HY-TEK's MEET MANAGER 8.0 - 12:40 PM 20/08/2026 Page 1\n2026 NCSC Best Time Ribbon Carnival - 21/08/2026 to 22/08/2026\nMeet Program - Session 1\nEvent 6 Mixed 50 SC Meter Butterfly\nLane Name Age Team Seed Time\nHeat 1 of 1 Finals Starts at 06:30 PM\n4 Matthew Callow 13 AQGCB 29.53`;
(async()=>{const browser=await chromium.launch({headless:true,args:['--no-sandbox']});const context=await browser.newContext({viewport:{width:390,height:844},isMobile:true,hasTouch:true});const page=await context.newPage();try{
 await page.goto(BASE,{waitUntil:'domcontentloaded'});await page.waitForFunction(()=>window.MSOS4?.storageEngine?.hydrated?.()===true,{timeout:10000});await page.waitForFunction(()=>document.body.dataset.guardian==='pass',{timeout:10000});
 await page.evaluate(()=>{const M=MSOS4;M.state.athletes=M.state.athletes||[];if(!M.state.athletes.some(a=>String(a.full_name||'').toLowerCase()==='matthew callow'))M.state.athletes.push({id:'sisc-matthew-callow',full_name:'Matthew Callow',squad:'National',active:true});M.state.meets=[];M.state.meetImports=[];M.state.meetFieldDeck=null;M.state.meetEntries=[];M.state.meetRaces=[];M.state.meetEvidence=[];M.state.meetProgramBA={sources:[],commentaries:[],meetWorkspaces:{},nowKey:'',selectedKey:'',selectedAthleteId:'',expandedKey:'',selectedSourceId:'',selectedEventNumber:0};M.state.meetOps={races:{},evidence:[],selectedAthleteId:'',selectedRaceKey:''};M.store.save(M.state);M.navigationEngine?.go?.('meet',{restore:false})});
 await page.waitForSelector('[data-meet-intake-au]',{timeout:5000});await page.click('[data-mfa-paste-btn]');await page.fill('[data-mfa-paste]',NORTH);await page.click('[data-mfa-process]');await page.waitForSelector('[data-mfa-use]',{timeout:3000});await page.click('[data-mfa-use]');await page.waitForSelector('[data-meet-program-ba]',{timeout:5000});
 const before=await page.evaluate(()=>({current:MSOS4.state.settings.currentMeetId,meets:MSOS4.state.meets,deck:MSOS4.state.meetFieldDeck,program:MSOS4.state.meetProgramBA,ops:MSOS4.state.meetOps,hasIntake:!!document.querySelector('[data-meet-intake-au]'),hasProgram:!!document.querySelector('[data-meet-program-ba]'),html:document.querySelector('#meetView')?.innerText?.slice(0,1200)}));console.log('BEFORE_NEW '+JSON.stringify(before));
 await page.click('[data-mwm-new]');await page.waitForSelector('[data-mwm-create]',{timeout:3000});await page.fill('[data-mwm-title]','South Island SC Champs');await page.fill('[data-mwm-date]','2026-08-28');await page.fill('[data-mwm-venue]','Moana pool');await page.selectOption('[data-mwm-course]','SCM');await page.click('[data-mwm-create]');await page.waitForTimeout(500);
 const after=await page.evaluate(()=>({current:MSOS4.state.settings.currentMeetId,meets:MSOS4.state.meets,deck:MSOS4.state.meetFieldDeck,program:MSOS4.state.meetProgramBA,ops:MSOS4.state.meetOps,workspaces:MSOS4.state.meetProgramBA?.meetWorkspaces,hasIntake:!!document.querySelector('[data-meet-intake-au]'),intakeVisible:(()=>{const e=document.querySelector('[data-meet-intake-au]');if(!e)return false;const r=e.getBoundingClientRect(),s=getComputedStyle(e);return r.height>0&&s.display!=='none'&&s.visibility!=='hidden'})(),hasProgram:!!document.querySelector('[data-meet-program-ba]'),hasField:!!document.querySelector('[data-meet-field-deck-au]'),html:document.querySelector('#meetView')?.innerText?.slice(0,1600)}));console.log('AFTER_NEW '+JSON.stringify(after));
}finally{await browser.close()}})().catch(e=>{console.error(e.stack||e);process.exit(1)});